import { createRouter, createWebHistory } from 'vue-router'
import authRoutes from '@/modules/login/router'
import registerRoutes from '@/modules/cadastro/router'
import dashboardRoutes from '@/modules/dashboard/router'

const routes = [
  ...authRoutes,
  ...registerRoutes,
  ...dashboardRoutes,
  { path: '', redirect: '/dashboard' },
  { path: '/:catchAll(.*)', redirect: '/dashboard' }
]

const router = createRouter({
  history: createWebHistory(),
  routes,
})

router.beforeEach(async (to, from, next) => {
  const token = window.localStorage.getItem('AUTH_TOKEN')
  if (to.matched.some(route => route.meta.requiredAuth)) {
    if (!token) {
      // Redireciona para o login se o token não existir
      return next({
        path: '/login',
        query: { redirect: to.fullPath } // Salva a rota para redirecionar após login
      })
    }

    try {
      // Se há token, permita o acesso
      return next()
    } catch (error) {
      // Se houver erro ao validar, redirecione para o login
      return next({
        path: '/login',
        query: { redirect: to.fullPath }
      })
    }
  }

  next();
});

export default router
